#include <catch2/catch_test_macros.hpp>

#include <algorithm>
#include <array>
#include <filesystem>
#include <fstream>
#include <iterator>
#include <set>
#include <string>
#include <string_view>

#include <nlohmann/json.hpp>

namespace
{

  std::filesystem::path source_root()
  {
    return std::filesystem::path{LIBBSA_SOURCE_DIR};
  }

  std::filesystem::path generated_archive_dir()
  {
    return source_root() / "tests" / "fixtures" / "generated" / "archives";
  }

  std::filesystem::path compatibility_matrix_path()
  {
    return source_root() / "tests" / "fixtures" / "generated" / "compatibility_matrix.json";
  }

  nlohmann::json read_json_file(const std::filesystem::path &path)
  {
    std::ifstream stream{path};
    REQUIRE(stream.is_open());
    return nlohmann::json::parse(stream);
  }

  std::string read_text_file(const std::filesystem::path &path)
  {
    std::ifstream stream{path};
    REQUIRE(stream.is_open());
    return std::string{std::istreambuf_iterator<char>{stream}, std::istreambuf_iterator<char>{}};
  }

  bool manifest_has_case_id(const nlohmann::json &manifest, std::string_view case_id)
  {
    const auto &cases = manifest.at("cases");
    return std::any_of(cases.begin(), cases.end(), [case_id](const nlohmann::json &test_case)
                       { return test_case.at("id").get<std::string>() == case_id; });
  }

  void require_required_matrix_keys(const nlohmann::json &row)
  {
    for (const auto key : {"id", "family", "category", "evidence_type", "phase", "expected_error"})
    {
      INFO("matrix row is missing key: " << key);
      REQUIRE(row.contains(key));
    }
  }

} // namespace

TEST_CASE("compatibility_matrix schema spans malformed families and risk categories",
          "[unit][fixture][malformed][compatibility_matrix]")
{
  REQUIRE(std::filesystem::is_regular_file(compatibility_matrix_path()));
  const auto matrix = read_json_file(compatibility_matrix_path());

  REQUIRE(matrix.at("matrix_kind").get<std::string>() == "phase11_malformed_hardening");
  REQUIRE(matrix.at("rows").is_array());

  const std::set<std::string> required_families{"tes3_bsa", "tes4_bsa", "ba2_gnrl", "ba2_dx10"};
  const std::set<std::string> required_categories{"truncated_structure",
                                                  "duplicate_canonical_path",
                                                  "invalid_payload_span",
                                                  "unsupported_route",
                                                  "decompression_failure",
                                                  "oversized_arithmetic",
                                                  "dds_chunk_layout"};
  const std::set<std::string> expected_errors{"format_error", "unsupported"};

  std::set<std::string> observed_families;
  std::set<std::string> observed_categories;

  for (const auto &row : matrix.at("rows"))
  {
    require_required_matrix_keys(row);

    const auto family = row.at("family").get<std::string>();
    const auto category = row.at("category").get<std::string>();
    const auto evidence_type = row.at("evidence_type").get<std::string>();
    const auto expected_error = row.at("expected_error").get<std::string>();

    INFO("compatibility_matrix row: " << row.at("id").get<std::string>());
    CHECK(required_families.contains(family));
    CHECK(required_categories.contains(category));
    CHECK((evidence_type == "manifest" || evidence_type == "test"));
    CHECK(expected_errors.contains(expected_error));

    observed_families.insert(family);
    observed_categories.insert(category);
  }

  for (const auto &family : required_families)
  {
    INFO("missing compatibility_matrix family: " << family);
    CHECK(observed_families.contains(family));
  }
  for (const auto &category : required_categories)
  {
    INFO("missing compatibility_matrix category: " << category);
    CHECK(observed_categories.contains(category));
  }
}

TEST_CASE("compatibility_matrix evidence references resolve to manifests or test tokens",
          "[unit][fixture][malformed][compatibility_matrix]")
{
  REQUIRE(std::filesystem::is_regular_file(compatibility_matrix_path()));
  const auto matrix = read_json_file(compatibility_matrix_path());

  bool observed_manifest_evidence = false;
  bool observed_test_evidence = false;

  for (const auto &row : matrix.at("rows"))
  {
    require_required_matrix_keys(row);
    const auto row_id = row.at("id").get<std::string>();
    const auto evidence_type = row.at("evidence_type").get<std::string>();
    INFO("compatibility_matrix evidence row: " << row_id);

    if (evidence_type == "manifest")
    {
      observed_manifest_evidence = true;
      for (const auto key : {"archive", "manifest", "case_id"})
      {
        INFO("manifest-backed row is missing key: " << key);
        REQUIRE(row.contains(key));
      }
      CHECK_FALSE(row.contains("test_file"));
      CHECK_FALSE(row.contains("test_name"));

      const auto archive = generated_archive_dir() / row.at("archive").get<std::string>();
      const auto manifest_path = generated_archive_dir() / row.at("manifest").get<std::string>();
      REQUIRE(std::filesystem::is_regular_file(archive));
      REQUIRE(std::filesystem::is_regular_file(manifest_path));

      const auto manifest = read_json_file(manifest_path);
      CHECK(manifest_has_case_id(manifest, row.at("case_id").get<std::string>()));
      continue;
    }

    REQUIRE(evidence_type == "test");
    observed_test_evidence = true;
    for (const auto key : {"test_file", "test_name"})
    {
      INFO("test-backed row is missing key: " << key);
      REQUIRE(row.contains(key));
    }
    CHECK_FALSE(row.contains("archive"));
    CHECK_FALSE(row.contains("manifest"));
    CHECK_FALSE(row.contains("case_id"));

    const auto test_file = source_root() / row.at("test_file").get<std::string>();
    REQUIRE(std::filesystem::is_regular_file(test_file));
    const auto test_text = read_text_file(test_file);
    CHECK(test_text.find(row.at("test_name").get<std::string>()) != std::string::npos);
  }

  CHECK(observed_manifest_evidence);
  CHECK(observed_test_evidence);
}

#include <catch2/catch_test_macros.hpp>

#include <array>
#include <filesystem>
#include <fstream>
#include <initializer_list>
#include <regex>
#include <sstream>
#include <string>
#include <string_view>

namespace
{

  std::filesystem::path source_root()
  {
    return std::filesystem::path{LIBBSA_SOURCE_DIR};
  }

  std::string read_text_file(const std::filesystem::path &path)
  {
    std::ifstream stream{path};
    REQUIRE(stream.is_open());

    std::ostringstream buffer;
    buffer << stream.rdbuf();
    return buffer.str();
  }

  void require_all_tokens(std::string_view text, std::initializer_list<std::string_view> tokens)
  {
    for (const auto token : tokens)
    {
      INFO("Missing token: " << token);
      REQUIRE(text.find(token) != std::string_view::npos);
    }
  }

  void require_no_tokens(std::string_view text, std::initializer_list<std::string_view> tokens)
  {
    for (const auto token : tokens)
    {
      INFO("Forbidden token: " << token);
      REQUIRE(text.find(token) == std::string_view::npos);
    }
  }

  void require_no_planning_identifier_patterns(std::string_view relative_path, const std::string &text)
  {
    struct ForbiddenPattern
    {
      std::string_view family;
      std::regex pattern;
    };

    const auto patterns = std::array{
        ForbiddenPattern{"phase label", std::regex{R"(\bphase\s+\d+\b)", std::regex_constants::icase}},
        ForbiddenPattern{"milestone label", std::regex{R"(\bmilestone\s+\d+\b)", std::regex_constants::icase}},
        ForbiddenPattern{"decision ID", std::regex{R"(\bD-\d+\b)", std::regex_constants::icase}},
    };

    for (const auto &forbidden : patterns)
    {
      INFO("Public documentation file: " << relative_path);
      INFO("Forbidden planning token family: " << forbidden.family);
      REQUIRE_FALSE(std::regex_search(text, forbidden.pattern));
    }
  }

} // namespace

TEST_CASE("docs_policy static boundary keeps public API documentation optional", "[unit][docs_policy][static_boundary]")
{
  const auto cmake = read_text_file(source_root() / "CMakeLists.txt");

  require_all_tokens(cmake,
                     {"find_package(Doxygen QUIET)",
                      "if(DOXYGEN_FOUND)",
                      "configure_file(",
                      "docs/Doxyfile.in",
                      "${CMAKE_CURRENT_BINARY_DIR}/Doxyfile",
                      "add_custom_target(libbsa_docs",
                      "${DOXYGEN_EXECUTABLE}",
                      "Doxygen not found; libbsa_docs target not available"});
}

TEST_CASE("docs_policy Doxyfile boundary documents public headers and excludes private inputs",
          "[unit][docs_policy][static_boundary]")
{
  const auto doxyfile = read_text_file(source_root() / "docs" / "Doxyfile.in");

  require_all_tokens(doxyfile,
                     {"PROJECT_NAME = libbsa",
                      "INPUT = @CMAKE_CURRENT_SOURCE_DIR@/include/libbsa",
                      "@CMAKE_CURRENT_SOURCE_DIR@/docs/api-mainpage.md",
                      "@CMAKE_CURRENT_SOURCE_DIR@/docs/thread-safety.md",
                      "RECURSIVE = YES",
                      "EXCLUDE = @CMAKE_CURRENT_SOURCE_DIR@/src",
                      "@CMAKE_CURRENT_SOURCE_DIR@/TES5Edit",
                      "@CMAKE_CURRENT_SOURCE_DIR@/tests",
                      "@CMAKE_CURRENT_BINARY_DIR@",
                      "GENERATE_HTML = YES",
                      "GENERATE_LATEX = NO",
                      "WARN_IF_UNDOCUMENTED = YES",
                      "WARN_AS_ERROR = NO",
                      "EXTRACT_PRIVATE = NO"});

  require_no_tokens(doxyfile,
                    {"INPUT = @CMAKE_CURRENT_SOURCE_DIR@/src",
                     "INPUT = @CMAKE_CURRENT_SOURCE_DIR@/TES5Edit",
                     "WARN_AS_ERROR = YES"});
}

TEST_CASE("docs_policy API mainpage preserves public operation structure", "[unit][docs_policy][doc_structure]")
{
  const auto mainpage = read_text_file(source_root() / "docs" / "api-mainpage.md");

  require_all_tokens(mainpage,
                     {"@mainpage",
                      "archive_reader",
                      "payload_sink",
                      "extract_entries",
                      "bulk_extract_options",
                      "bulk_extract_sink_factory",
                      "bulk_extract_entry_result",
                      "tes3_bsa_writer",
                      "tes4_bsa_writer",
                      "ba2_gnrl_writer",
                      "ba2_dx10_writer",
                      "write_execution_options",
                      "validate_archive",
                      "validation_report",
                      "@ref thread_safety",
                      "target-format guide"});
}

TEST_CASE("docs_policy public documentation surfaces hide planning identifiers",
          "[unit][docs_policy][doc_structure]")
{
  const auto root = source_root();
  constexpr auto public_documentation_files = std::array{
      "include/libbsa/archive.hpp",
      "include/libbsa/writer.hpp",
      "docs/thread-safety.md",
      "docs/compatibility-evidence.md",
      "tests/fixtures/README.md",
  };

  for (const auto relative_path : public_documentation_files)
  {
    const auto text = read_text_file(root / relative_path);
    require_no_planning_identifier_patterns(relative_path, text);
  }
}

#include <catch2/catch_test_macros.hpp>

#include <algorithm>
#include <array>
#include <cctype>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

namespace
{

  std::filesystem::path source_root()
  {
    return std::filesystem::path{LIBBSA_SOURCE_DIR};
  }

  std::string read_text_file(const std::filesystem::path &path)
  {
    std::ifstream stream{path};
    REQUIRE(stream.is_open());

    std::ostringstream buffer;
    buffer << stream.rdbuf();
    return buffer.str();
  }

  std::string trim_copy(std::string value)
  {
    const auto first = std::find_if(value.begin(), value.end(), [](unsigned char ch)
                                    { return !std::isspace(ch); });
    const auto last = std::find_if(value.rbegin(), value.rend(), [](unsigned char ch)
                                   { return !std::isspace(ch); })
                          .base();

    if (first >= last)
    {
      return {};
    }
    return std::string{first, last};
  }

  std::vector<std::string> compatibility_warning_codes_from_public_header()
  {
    const auto header = read_text_file(source_root() / "include/libbsa/validation.hpp");
    const auto enum_name = std::string{"enum class compatibility_warning_code"};
    const auto enum_start = header.find(enum_name);
    REQUIRE(enum_start != std::string::npos);

    const auto body_start = header.find('{', enum_start);
    REQUIRE(body_start != std::string::npos);
    const auto body_end = header.find("};", body_start);
    REQUIRE(body_end != std::string::npos);

    std::vector<std::string> codes;
    std::istringstream lines{header.substr(body_start + 1, body_end - body_start - 1)};
    std::string line;
    while (std::getline(lines, line))
    {
      if (const auto comment = line.find("//"); comment != std::string::npos)
      {
        line.erase(comment);
      }
      if (const auto comma = line.find(','); comma != std::string::npos)
      {
        line.erase(comma);
      }

      auto code = trim_copy(line);
      if (!code.empty())
      {
        codes.push_back(std::move(code));
      }
    }
    return codes;
  }

  bool guide_has_warning_entry(const std::string &guide, const std::string &code)
  {
    return guide.find("### `" + code + "`") != std::string::npos ||
           guide.find("`" + code + "`") != std::string::npos;
  }

} // namespace

TEST_CASE("target_format_policy package consumer examples have docs and CTest smoke gates",
          "[unit][target_format_policy][package_consumer][doc_structure]")
{
  const auto root = source_root();
  const auto docs = read_text_file(root / "docs/integration-examples.md");
  const auto tests_cmake = read_text_file(root / "tests/CMakeLists.txt");

  constexpr std::array<std::string_view, 8> examples{
      "example_open_list_extract",
      "example_bulk_extract",
      "example_create_tes3_bsa",
      "example_create_tes4_bsa",
      "example_create_ba2_gnrl",
