const fs = require('fs');
const path = require('path');
const dir = 'tests/fixtures/generated/archives';
const counts = {};
for (const file of fs.readdirSync(dir)) {
  if (!/\.(bsa|ba2)$/i.test(file)) continue;
  const family = file.startsWith('tes3_') ? 'tes3_bsa'
    : file.startsWith('tes4_') ? 'tes4_bsa'
    : file.startsWith('ba2_gnrl_') ? 'ba2_gnrl'
    : file.startsWith('ba2_dx10_') ? 'ba2_dx10'
    : file.startsWith('malformed_') ? 'tes4_bsa'
    : 'other';
  counts[family] = counts[family] || {success:0, malformed:0, files:[]};
  counts[family].files.push(file);
  if (file.includes('success') || file.includes('_fo4') || file.includes('_sfv')) counts[family].success++;
  else counts[family].malformed++;
}
for (const family of Object.keys(counts).sort()) {
  const c = counts[family];
  console.log(`${family}: success-ish=${c.success} malformed-ish=${c.malformed} total=${c.files.length}`);
}

